"""Todo store. Generated by a coding agent; adopted into chatop in Lab 3."""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from pathlib import Path


@dataclass
class Todo:
    id: int
    title: str
    done: bool = False


class TodoStore:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.items: list[Todo] = []
        if path.exists():
            self.items = [Todo(**d) for d in json.loads(path.read_text())]

    def add(self, title: str) -> Todo:
        todo = Todo(id=len(self.items) + 1, title=title)
        self.items.append(todo)
        self._save()
        return todo

    def complete(self, todo_id: int) -> None:
        for t in self.items:
            if t.id == todo_id:
                t.done = True
        self._save()

    def open_items(self) -> list[Todo]:
        return [t for t in self.items if not t.done]

    def _save(self) -> None:
        self.path.write_text(json.dumps([asdict(t) for t in self.items]))
